sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 from;
uniform float2 to;
layout(color) uniform half4 color;
layout(color) uniform half4 haloColor;
uniform float width;
uniform float glow;
uniform float halo;
uniform float haloWidth;
uniform float progress;
uniform float span;
uniform float wiggle;
uniform float frequency;
uniform float evolution;
uniform float opacity;
uniform float dim;
uniform float blend;
float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}
float hash21(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + float2(1, 0)), f.x), mix(hash21(i + float2(0, 1)), hash21(i + float2(1, 1)), f.x), f.y);
}
float fbm(float2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        s += a * vnoise(p);
        p = p * 2.03 + float2(17.1, 9.7);
        a *= 0.5;
    }
    return s / 0.96875;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 a = 0.5 * size + from;
    float2 ab = to - from;
    float len = max(length(ab), 1.0);
    float2 dir = ab / len;
    float2 q = coord - a;
    float t = dot(q, dir) / len;
    float s = dot(q, float2(-dir.y, dir.x));
    float w = vnoise(float2(t * frequency + evolution, 3.7)) + 0.5 * vnoise(float2(t * frequency * 2.7 + evolution * 1.7, 11.3)) - 0.75;
    s -= w * wiggle * len * 0.2 * sin(3.1415927 * clamp(t, 0.0, 1.0));
    float t1 = clamp(progress, 0.0, 1.0);
    float t0 = clamp(progress - span, 0.0, 1.0);
    if (t1 <= t0) return src;
    float tc = clamp(t, t0, t1);
    float d = length(float2((t - tc) * len, s));
    float body = mix(0.3, 1.0, (tc - t0) / (t1 - t0));
    float u = max(width, 0.5);
    float core = (1.0 - smoothstep(u * 0.15, u * 0.45, d)) * body;
    float near = exp(-d / (u * 1.2)) * glow * body * float(color.a);
    float far = exp(-d / max(haloWidth, 0.5)) * halo * body * float(haloColor.a);
    float3 light = (float3(color.rgb) * near + float3(haloColor.rgb) * far + float3(core)) * opacity;
    float3 base = float3(src.rgb) / float(src.a) * (1.0 - dim);
    float3 rgb;
    if (blend < 0.5) rgb = base + light;
    else if (blend < 1.5) rgb = 1.0 - (1.0 - base) * (1.0 - clamp(light, 0.0, 1.0));
    else rgb = mix(base, float3(color.rgb), clamp(max(max(light.r, light.g), light.b), 0.0, 1.0));
    return half4(half3(clamp(rgb, 0.0, 1.0)) * src.a, src.a);
}
